"""Literal fixed-source business CSS, evaluated only as known scalar slots."""
import re

WARDLEY='\n  .wardley-background {\n    fill: ${w.backgroundColor};\n  }\n  .wardley-axes line, .wardley-axes path {\n    stroke: ${w.axisColor};\n  }\n  .wardley-axis-label {\n    fill: ${w.axisTextColor};\n  }\n  .wardley-stage-label {\n    fill: ${w.axisTextColor};\n  }\n  .wardley-grid line {\n    stroke: ${w.gridColor};\n  }\n  .wardley-node circle {\n    fill: ${w.componentFill};\n    stroke: ${w.componentStroke};\n  }\n  .wardley-node-label {\n    fill: ${w.componentLabelColor};\n  }\n  .wardley-link {\n    stroke: ${w.linkStroke};\n  }\n  .wardley-link--dashed {\n    stroke-dasharray: 4 4;\n  }\n  .wardley-link-label {\n    fill: ${w.axisTextColor};\n  }\n  .wardley-trend line {\n    stroke: ${w.evolutionStroke};\n  }\n  .wardley-annotation-line {\n    stroke: ${w.annotationStroke};\n  }\n  .wardley-annotation circle {\n    fill: ${w.annotationFill};\n    stroke: ${w.annotationStroke};\n  }\n  .wardley-annotation text {\n    fill: ${w.annotationTextColor};\n  }\n  .wardley-annotations-box rect {\n    fill: ${w.annotationFill};\n    stroke: ${w.annotationStroke};\n  }\n  .wardley-annotations-box text {\n    fill: ${w.annotationTextColor};\n  }\n  .wardley-pipeline-box {\n    stroke: ${w.componentStroke};\n  }\n  .wardley-notes text {\n    fill: ${w.axisTextColor};\n  }\n  '
CYNEFIN='\n\t.cynefinDomain {\n\t\tstroke: none;\n\t}\n\t.cynefinDomainLabel {\n\t\tfont-size: ${t.domainFontSize}px;\n\t\tfont-weight: bold;\n\t\tfill: ${t.labelColor};\n\t}\n\t.cynefinSubtitle {\n\t\tfont-size: ${t.itemFontSize - 1}px;\n\t\tfill: ${t.textColor};\n\t\tfont-style: italic;\n\t}\n\t.cynefinItem {\n\t\tfill-opacity: 0.95;\n\t\tstroke: ${t.boundaryColor};\n\t\tstroke-width: 1;\n\t}\n\t.cynefinItemText {\n\t\tfont-size: ${t.itemFontSize}px;\n\t\tfill: ${t.textColor};\n\t}\n\t.cynefinItemOverflow {\n\t\tfill-opacity: 0.6;\n\t\tstroke: ${t.boundaryColor};\n\t\tstroke-width: 1;\n\t\tstroke-dasharray: 3 2;\n\t}\n\t.cynefinBoundary {\n\t\tstroke: ${t.boundaryColor};\n\t\tstroke-width: ${t.boundaryWidth};\n\t\tstroke-dasharray: 6 3;\n\t}\n\t.cynefinCliff {\n\t\tstroke: ${t.cliffColor};\n\t\tstroke-width: ${t.cliffWidth};\n\t}\n\t.cynefinConfusion {\n\t\tstroke: ${t.boundaryColor};\n\t\tstroke-width: 1.5;\n\t\tstroke-dasharray: 4 2;\n\t}\n\t.cynefinArrowLine {\n\t\tstroke: ${t.arrowColor};\n\t\tstroke-width: ${t.arrowWidth};\n\t\tfill: none;\n\t}\n\t.cynefinArrowHead {\n\t\tfill: ${t.arrowColor};\n\t\tstroke: none;\n\t}\n\t.cynefinArrowLabel {\n\t\tfont-size: ${t.itemFontSize - 1}px;\n\t\tfill: ${t.textColor};\n\t}\n\t.cynefinTitle {\n\t\tfont-size: ${t.domainFontSize + 2}px;\n\t\tfont-weight: bold;\n\t\tfill: ${t.labelColor};\n\t}\n\t'
ISHIKAWA='\n.ishikawa .ishikawa-spine,\n.ishikawa .ishikawa-branch,\n.ishikawa .ishikawa-sub-branch {\n  stroke: ${options.lineColor};\n  stroke-width: 2;\n  fill: none;\n}\n\n.ishikawa .ishikawa-sub-branch {\n  stroke-width: 1;\n}\n\n.ishikawa .ishikawa-arrow {\n  fill: ${options.lineColor};\n}\n\n.ishikawa .ishikawa-head {\n  fill: ${options.mainBkg};\n  stroke: ${options.lineColor};\n  stroke-width: 2;\n}\n\n.ishikawa .ishikawa-label-box {\n  fill: ${options.mainBkg};\n  stroke: ${options.lineColor};\n  stroke-width: 2;\n}\n\n.ishikawa text {\n  font-family: ${options.fontFamily};\n  font-size: ${options.fontSize};\n  fill: ${options.textColor};\n}\n\n.ishikawa .ishikawa-head-label {\n  font-weight: 600;\n  text-anchor: middle;\n  dominant-baseline: middle;\n  font-size: 14px;\n}\n\n.ishikawa .ishikawa-label {\n  text-anchor: end;\n}\n\n.ishikawa .ishikawa-label.cause {\n  text-anchor: middle;\n  dominant-baseline: middle;\n}\n\n.ishikawa .ishikawa-label.align {\n  text-anchor: end;\n  dominant-baseline: middle;\n}\n\n.ishikawa .ishikawa-label.up {\n  dominant-baseline: baseline;\n}\n\n.ishikawa .ishikawa-label.down {\n  dominant-baseline: hanging;\n}\n'

def styles(kind,values):
    template={'wardley':WARDLEY,'cynefin':CYNEFIN,'ishikawa':ISHIKAWA}[kind]
    def value(match):
        expr=match[1];m=re.fullmatch(r'(?:w|t|options)\.(\w+)(?:\s*([+-])\s*(\d+))?',expr)
        if not m:raise ValueError('Unrecognized fixed style slot '+expr)
        result=values.get(m[1])
        if m[2]:result=float(result)+(1 if m[2]=='+' else -1)*int(m[3])
        return 'undefined' if result is None else str(result)
    css=re.sub(r'\$\{([^{}]+)\}',value,template)
    # Text anchor/baseline placement is represented by explicit pure geometry
    # in each source-specific renderer, rather than applying it a second time.
    return re.sub(r'(?:dominant-baseline|text-anchor)\s*:[^;{}]*;','',css)
